import java.util.stream.Collectors;

class DelegatingDeviceTracker {
    private final Map<Integer, Position> positions = new ConcurrentHashMap<>();

    public void initialize(Map<Integer, Position> initialPositions) {
        positions.putAll(initialPositions);
    }

    public Position getPosition(int deviceId) {
        return positions.get(deviceId);
    }

    public boolean updatePosition(int deviceId, Position newPosition) {
        return positions.replace(deviceId, newPosition) != null;
    }

    public Map<Integer, Position> getAllPositions() {
        return new ConcurrentHashMap<>(positions);
    }

    public List<Position> snapshotAllPositions() {
        return positions.values().stream()
                .collect(Collectors.toList());
    }
}

