import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Integer> positions = new ConcurrentHashMap<>();
    private static volatile boolean started = false;

    public DelegatingDeviceTracker(Map<String, Integer> initialPositions) {
        for (Map.Entry<String, Integer> entry : initialPositions.entrySet()) {
            positions.put(entry.getKey(), entry.getValue());
        }
    }

    public int getPosition(String deviceId) {
        return positions.get(deviceId);
    }

    public void updatePosition(String deviceId, int newPosition) {
        if (!positions.containsKey(deviceId)) {
            throw new RuntimeException("Device ID does not exist");
        }
        positions.compute(deviceId, (id, oldPosition) -> newPosition);
    }

    public static Map<String, Integer> getAllPositionsStatic() {
        ConcurrentHashMap<String, Integer> temp = new ConcurrentHashMap<>(positions);
        return Collections.unmodifiableMap(temp);
    }

    public Map<String, Integer> getAllPositionsLive() {
        return positions;
    }

    private class TrackerThread implements Runnable {

        @Override
        public void run() {
            while (!started) {
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
            System.out.println("Positions: " + getAllPositionsStatic());
        }

    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(Map.of("001", 100, "002", 200));

        Thread t1 = new Thread(tracker.new TrackerThread());
        Thread t2 = new Thread(tracker.new TrackerThread());

        started = true;
        t1.start();
        t2.start();

        while (true) {
            tracker.updatePosition("001", 150);
            System.out.println("New position of gadget 001: " + tracker.getPosition("001"));

            Thread.sleep(1000);
        }
    }
}

