import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

class DelegatingParcelTracker {
    private final Map<Integer, Integer> positions = new ConcurrentHashMap<>();

    public int getPosition(int packageId) {
        return positions.get(packageId);
    }

    public boolean setPosition(int packageId, int newPosition) {
        if (positions.containsKey(packageId)) {
            positions.put(packageId, newPosition);
            return true;
        }
        return false;
    }

    public Set<Map.Entry<Integer, Integer>> getPositionsAsSet() {
        return positions.entrySet();
    }

    public Map<Integer, Integer> getPositions() {
        return new ConcurrentHashMap<>(positions);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        DelegatingParcelTracker tracker = new DelegatingParcelTracker();

        // Initialize with initial positions
        Set<Map.Entry<Integer, Integer>> initPositions = tracker.getPositionsAsSet().stream()
                .filter(e -> e.getKey() == 1 || e.getKey() == 2)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

        for (Map.Entry<Integer, Integer> entry : initPositions) {
            int packageId = entry.getKey();
            int position = entry.getValue();

            new Thread(() -> {
                try {
                    tracker.setPosition(packageId, position + 1);
                } catch (Exception e) {
                    System.out.println("Failed to update position for package " + packageId);
                }
            }).start();
        }

        // Wait for threads to finish
        Thread.sleep(1000);

        // Retrieve positions
        Set<Map.Entry<Integer, Integer>> retrievedPositions = tracker.getPositionsAsSet().stream()
                .filter(e -> e.getKey() == 1 || e.getKey() == 2)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

        for (Map.Entry<Integer, Integer> entry : retrievedPositions) {
            System.out.println("Package ID: " + entry.getKey() + ", Position: " + entry.getValue());
        }

        // Retrieve live map of positions
        Map<Integer, Integer> liveMap = tracker.getPositions();
        System.out.println(liveMap);

        // Retrieve snapshot of positions (should be identical to retrieved positions)
        Map<Integer, Integer> snapshot = tracker.getPositions();
        System.out.println(snapshot);
    }
}

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingParcelTracker {

    private final ConcurrentHashMap<Integer, Integer> positions;

    public DelegatingParcelTracker(Map<Integer, Integer> initialPositions) {
        this.positions = new ConcurrentHashMap<>(initialPositions);
    }

    public int getPosition(int packageId) {
        return positions.get(packageId);
    }

    public boolean assignPosition(int packageId, int newPosition) {
        return positions.computeIfPresent(packageId, (id, oldPos) -> oldPos = newPosition) != null;
    }

    public Map<Integer, Integer> getAllPositions() {
        return new ConcurrentHashMap<>(positions);
    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingParcelTracker tracker = new DelegatingParcelTracker(Map.of(1, 10, 2, 20));

        Thread thread = new Thread(() -> {
            System.out.println("Thread started");

            for (int i = 0; i < 1000000; i++) {
                int packageId = i % 3 + 1;
                tracker.assignPosition(packageId, i);

                if (i % 10_000 == 0) {
                    System.out.println("All positions: " + tracker.getAllPositions());
                }
            }

            System.out.println("Thread finished");
        });

        thread.start();

        while (true) {
            int packageId = 3;
            int newPosition = 30;

            if (!tracker.assignPosition(packageId, newPosition)) {
                break;
            }

            Map<Integer, Integer> positions = tracker.getAllPositions();
            System.out.println("Positions: " + positions);

            Thread.sleep(1000);
        }
    }
}

