import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingRobotTracker {
    private final ConcurrentHashMap<String, Coordinate> robotCoordinates = new ConcurrentHashMap<>();

    public void setCoordinate(String robotId, int x, int y) {
        if (robotCoordinates.containsKey(robotId)) {
            Coordinates oldCoordinates = robotCoordinates.get(robotId);
            robotCoordinates.put(robotId, new Coordinate(x, y));
        }
    }

    public boolean containsKey(String robotId) {
        return robotCoordinates.containsKey(robotId);
    }

    public Map<String, Coordinate> getAllCoordinatesSnapshot() {
        return new ConcurrentHashMap<>(robotCoordinates);
    }

    public Map<String, Coordinate> getAllCoordinatesLive() {
        return robotCoordinates;
    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingRobotTracker tracker = new DelegatingRobotTracker();
        tracker.setCoordinate("Robo1", 0, 0);
        tracker.setCoordinate("Robo2", 5, 5);

        System.out.println(tracker.getAllCoordinatesLive());
        Map<String, Coordinate> snapshot = tracker.getAllCoordinatesSnapshot();
        for (Map.Entry<String, Coordinate> entry : snapshot.entrySet()) {
            System.out.printf("%s: (%d,%d)\n", entry.getKey(), entry.getValue().getX(), entry.getValue().getY());
        }

        // Create a thread to modify robot coordinates
        Thread modifyThread = new Thread(() -> {
            try {
                tracker.setCoordinate("Robo1", 10, 10);
                System.out.println(tracker.getAllCoordinatesLive());
            } catch (Exception e) {
                e.printStackTrace();
            }
        });
        modifyThread.start();

        // Join the thread to ensure the program ends after it finishes
        modifyThread.join();
    }

    static class Coordinate {
        private final int x;
        private final int y;

        public Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }
    }
}

import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class DelegatingRobotTracker implements Runnable {

    private ConcurrentHashMap<Integer, Integer> robotCoordinates = new ConcurrentHashMap<>();

    public void initialize(int[] initialCoordinates) {
        for (int i = 0; i < initialCoordinates.length / 2; i++) {
            robotCoordinates.put(i, initialCoordinates[i * 2]);
        }
    }

    public int getRobotCoordinate(int robotId) {
        return robotCoordinates.getOrDefault(robotId, -1);
    }

    public boolean setRobotCoordinate(int robotId, int x, int y) {
        if (robotCoordinates.containsKey(robotId)) {
            synchronized (this) {
                robotCoordinates.put(robotId, x);
            }
            return true;
        } else {
            return false;
        }
    }

    public ConcurrentHashMap<Integer, Integer> getLiveRobotCoordinates() {
        return new ConcurrentHashMap<>(robotCoordinates);
    }

    public static void main(String[] args) {
        DelegatingRobotTracker tracker = new DelegatingRobotTracker();
        int[] initialCoordinates = {0, 1, 2, 3, 4, 5};
        tracker.initialize(initialCoordinates);

        // Create a new thread to track changes
        Thread trackerThread = new Thread(tracker);
        trackerThread.start();

        System.out.println("Live Coordinates: " + tracker.getLiveRobotCoordinates());

        // Modify coordinates from main thread
        tracker.setRobotCoordinate(0, 10, 20);
        System.out.println("Modified Live Coordinates (from Main): " + tracker.getLiveRobotCoordinates());

        // Wait for the changes to reflect in live view
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        // Create a new thread to track changes again
        Thread trackerThread2 = new Thread(tracker);
        trackerThread2.start();

        System.out.println("Live Coordinates: " + tracker.getLiveRobotCoordinates());

        // Modify coordinates from main thread
        tracker.setRobotCoordinate(1, 15, 25);
        System.out.println("Modified Live Coordinates (from Main): " + tracker.getLiveRobotCoordinates());
    }
}

import java.util.Collection;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

class DelegatingRobotTracker {
    private final ConcurrentHashMap<Integer, int[]> trackerMap;

    public DelegatingRobotTracker(Collection<Coordinate> initialCoordinates) {
        trackerMap = new ConcurrentHashMap<>();
        for (var coordinate : initialCoordinates) {
            if (coordinate != null) {
                trackerMap.put(coordinate.robotId, coordinate.coordinates);
            }
        }
    }

    public int[] getRobotCoordinates(int robotId) {
        return trackerMap.getOrDefault(robotId, new int[0]);
    }

    public void setRobotCoordinates(int robotId, int[] coordinates) {
        if (trackerMap.containsKey(robotId)) {
            trackerMap.put(robotId, coordinates);
        }
    }

    public Collection<int[]> getAllRobotCoordinates() {
        return Collections.unmodifiableCollection(trackerMap.values());
    }

    public Collection<int[]> getStaticAllRobotCoordinates() {
        var staticCopy = new ConcurrentHashMap<Integer, int[]>();
        for (var pair : trackerMap.entrySet()) {
            staticCopy.put(pair.getKey(), pair.getValue().clone());
        }
        return Collections.unmodifiableCollection(staticCopy.values());
    }

    private static class Coordinate implements Runnable {
        final int robotId;
        final int[] coordinates;

        public Coordinate(int robotId, int[] coordinates) {
            this.robotId = robotId;
            this.coordinates = coordinates;
        }

        @Override
        public void run() {
            try {
                Thread.sleep(500); // Simulate some delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            System.out.println("Initializing coordinates for Robot " + robotId);
            DelegatingRobotTracker.this.setRobotCoordinates(robotId, new int[]{robotId % 1000, robotId % 100});
        }
    }

    public static void main(String[] args) throws InterruptedException {
        var tracker = new DelegatingRobotTracker(
                Arrays.asList(new Coordinate(1, new int[]{10, 20}), new Coordinate(2, new int[]{30, 40})));

        // Use a fixed thread pool with at most 2 additional threads
        var executorService = Executors.newFixedThreadPool(3);

        // Submit tasks to the Executor
        executorService.execute(tracker);
        executorService.shutdown();

        while (!executorService.isTerminated()) {
            // Waiting for all threads to finish their execution.
        }

        System.out.println("All robots initialized.");

        // Retrieve and print robot coordinates
        var liveCoordinates = tracker.getAllRobotCoordinates();
        System.out.println("Live Robot Coordinates: " + liveCoordinates);

        var staticCoordinates = tracker.getStaticAllRobotCoordinates();
        System.out.println("Static Robot Coordinates: " + staticCoordinates);

    }
}

