import java.util.concurrent.*;

public class Locker {
    private int count;

    public synchronized void increment() {
        this.count++;
    }

    public synchronized int getCount() {
        return count;
    }
}

class ParcelCount extends Thread {
    private Locker sourceLocker;
    private Locker targetLocker;
    private int quantityToMove;
    private Random random = new Random();

    public ParcelCount(Locker sourceLocker, Locker targetLocker, int quantityToMove) {
        this.sourceLocker = sourceLocker;
        this.targetLocker = targetLocker;
        this.quantityToMove = quantityToMove;
    }

    @Override
    public void run() {
        try {
            boolean success = false;

            while (!success && !Thread.currentThread().isInterrupted()) {
                if (sourceLocker.getCount() < quantityToMove) {
                    throw new NotEnoughItemsException("Not enough items in the source locker");
                }
                sourceLocker.increment();
                targetLocker.increment();

                double randomDelay = Math.random() * 1000;
                Thread.sleep(randomDelay);
            }

            System.out.println(quantityToMove + " parcels moved from " + sourceLocker + " to " + targetLocker);
        } catch (InterruptedException | NotEnoughItemsException e) {
            System.out.println(e.getMessage());
        }
    }
}

class NotEnoughItemsException extends Exception {
    public NotEnoughItemsException(String message) {
        super(message);
    }
}

public class DeadlockAvoidance {
    private static final int MAX_ATTEMPTS = 5;

    public static void move(Locker sourceLocker, Locker targetLocker, int quantityToMove, long timeout, TimeUnit timeUnit) throws InterruptedException, NotEnoughItemsException {
        boolean success = false;
        int attempts = 0;

        while (!success && attempts < MAX_ATTEMPTS) {
            if (sourceLocker.getCount() < quantityToMove) {
                throw new NotEnoughItemsException("Not enough items in the source locker");
            }

            long startTime = System.nanoTime();
            boolean lock1Acquired = false;
            boolean lock2Acquired = false;

            while (!lock1Acquired || !lock2Acquired) {
                if (System.nanoTime() - startTime > timeout * 1000) {
                    break;
                }

                // Lock source locker
                try {
                    lock1Acquired = sourceLocker.tryLock(timeout, timeUnit);
                } catch (InterruptedException ignore) {
                }
                if (!lock1Acquired) {
                    continue;
                }

                // Lock target locker after acquiring the source locker
                try {
                    lock2Acquired = targetLocker.tryLock(timeout, timeUnit);
                } catch (InterruptedException ignore) {
                }
                if (!lock2Acquired) {
                    lock1Acquired = false;
                }
            }

            if (lock1Acquired && lock2Acquired) {
                sourceLocker.increment(quantityToMove);
                targetLocker.increment(quantityToMove);
                success = true;
            } else {
                throw new NotEnoughItemsException("Timeout for acquiring the locks");
            }
        }

        if (!success) {
            throw new NotEnoughItemsException("Could not acquire both locks in time");
        }
    }

    public static void main(String[] args) throws InterruptedException, NotEnoughItemsException {
        Locker sourceLocker = new Locker();
        Locker targetLocker = new Locker();

        ExecutorService executorService = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 10; ++i) {
            int quantityToMove = (int) (Math.random() * 20);
            executorService.execute(new ParcelCount(sourceLocker, targetLocker, quantityToMove));
        }

        try {
            move(sourceLocker, targetLocker, 5, 5, TimeUnit.SECONDS);
        } catch (NotEnoughItemsException e) {
            System.out.println(e.getMessage());
        }

        executorService.shutdown();
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;
import java.util.Random;

public class LockerSystem implements Runnable {
    private static final int MAX_ATTEMPTS = 5;
    private static final long INITIAL_DELAY = 1000;
    private static final Random RANDOM = new Random();

    private ReentrantLock sourceLockerLock;
    private ReentrantLock targetLockerLock;
    private ParcelCount sourceParcelCount;
    private ParcelCount targetParcelCount;

    public LockerSystem(ReentrantLock sourceLockerLock, ReentrantLock targetLockerLock,
                         ParcelCount sourceParcelCount, ParcelCount targetParcelCount) {
        this.sourceLockerLock = sourceLockerLock;
        this.targetLockerLock = targetLockerLock;
        this.sourceParcelCount = sourceParcelCount;
        this.targetParcelCount = targetParcelCount;
    }

    @Override
    public void run() {
        while (true) {
            try {
                if (attemptMove(1000, TimeUnit.MILLISECONDS)) {
                    break;
                }
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
        }
    }

    private boolean attemptMove(long timeout, TimeUnit timeUnit) throws NotEnoughItemsException {
        int attempts = 0;
        long delay = INITIAL_DELAY;

        while (true) {
            if (acquireLocks(sourceLockerLock, targetLockerLock)) {
                try {
                    if (!sourceParcelCount.hasSufficientQuantity(1)) {
                        throw new NotEnoughItemsException("Source locker does not have enough items");
                    }

                    sourceParcelCount.decrement();
                    targetParcelCount.increment();

                    return true;
                } finally {
                    releaseLocks(sourceLockerLock, targetLockerLock);
                }
            }

            attempts++;

            if (attempts >= MAX_ATTEMPTS) {
                return false;
            }

            try {
                Thread.sleep(timeUnit.toMillis(delay));
                delay = calculateNewDelay(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private boolean acquireLocks(ReentrantLock... locks) {
        for (ReentrantLock lock : locks) {
            if (!lock.tryLock(MAX_ATTEMPTS, TimeUnit.MILLISECONDS)) {
                return false;
            }
        }
        return true;
    }

    private void releaseLocks(ReentrantLock... locks) {
        for (ReentrantLock lock : locks) {
            lock.unlock();
        }
    }

    private long calculateNewDelay(long currentDelay) {
        double randomFactor = 1 + RANDOM.nextDouble();
        return (long) (currentDelay * randomFactor);
    }

    public static void main(String[] args) {
        ReentrantLock sourceLocker = new ReentrantLock();
        ReentrantLock targetLocker = new ReentrantLock();

        ParcelCount sourceParcelCount = new ParcelCount(5);
        ParcelCount targetParcelCount = new ParcelCount(0);

        LockerSystem system = new LockerSystem(sourceLocker, targetLocker, sourceParcelCount, targetParcelCount);

        Thread worker = new Thread(system);
        worker.start();
