import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;
import java.util.Random;

public class LockerSystem implements Runnable {
    private static final int MAX_ATTEMPTS = 5;
    private static final long INITIAL_DELAY = 1000;
    private static final Random RANDOM = new Random();

    private ReentrantLock sourceLockerLock;
    private ReentrantLock targetLockerLock;
    private ParcelCount sourceParcelCount;
    private ParcelCount targetParcelCount;

    public LockerSystem(ReentrantLock sourceLockerLock, ReentrantLock targetLockerLock,
                         ParcelCount sourceParcelCount, ParcelCount targetParcelCount) {
        this.sourceLockerLock = sourceLockerLock;
        this.targetLockerLock = targetLockerLock;
        this.sourceParcelCount = sourceParcelCount;
        this.targetParcelCount = targetParcelCount;
    }

    @Override
    public void run() {
        while (true) {
            try {
                if (attemptMove(1000, TimeUnit.MILLISECONDS)) {
                    break;
                }
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
        }
    }

    private boolean attemptMove(long timeout, TimeUnit timeUnit) throws NotEnoughItemsException {
        int attempts = 0;
        long delay = INITIAL_DELAY;

        while (true) {
            if (acquireLocks(sourceLockerLock, targetLockerLock)) {
                try {
                    if (!sourceParcelCount.hasSufficientQuantity(1)) {
                        throw new NotEnoughItemsException("Source locker does not have enough items");
                    }

                    sourceParcelCount.decrement();
                    targetParcelCount.increment();

                    return true;
                } finally {
                    releaseLocks(sourceLockerLock, targetLockerLock);
                }
            }

            attempts++;

            if (attempts >= MAX_ATTEMPTS) {
                return false;
            }

            try {
                Thread.sleep(timeUnit.toMillis(delay));
                delay = calculateNewDelay(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    private boolean acquireLocks(ReentrantLock... locks) {
        for (ReentrantLock lock : locks) {
            if (!lock.tryLock(MAX_ATTEMPTS, TimeUnit.MILLISECONDS)) {
                return false;
            }
        }
        return true;
    }

    private void releaseLocks(ReentrantLock... locks) {
        for (ReentrantLock lock : locks) {
            lock.unlock();
        }
    }

    private long calculateNewDelay(long currentDelay) {
        double randomFactor = 1 + RANDOM.nextDouble();
        return (long) (currentDelay * randomFactor);
    }

    public static void main(String[] args) {
        ReentrantLock sourceLocker = new ReentrantLock();
        ReentrantLock targetLocker = new ReentrantLock();

        ParcelCount sourceParcelCount = new ParcelCount(5);
        ParcelCount targetParcelCount = new ParcelCount(0);

        LockerSystem system = new LockerSystem(sourceLocker, targetLocker, sourceParcelCount, targetParcelCount);

        Thread worker = new Thread(system);
        worker.start();
    }

    static class ParcelCount {
        private int quantity;

        public ParcelCount(int initialQuantity) {
            this.quantity = initialQuantity;
        }

        public synchronized void increment() {
            quantity++;
        }

        public synchronized void decrement() {
            quantity--;
        }

        public boolean hasSufficientQuantity(int quantityToMove) {
            return this.quantity >= quantityToMove;
        }
    }

    static class Locker {
