import java.util.concurrent.*;

public class DeadlockAvoidance {

    static final int MAX_ATTEMPTS = 5;
    static final long INITIAL_DELAY = 0L;

    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    static class ElementCount implements Runnable {
        private volatile int count;

        synchronized void add(int increment) {
            while (count + increment < 0) {
                wait();
            }
            count += increment;
        }

        synchronized int getCount() {
            return count;
        }
    }

    static class Container implements Runnable {
        private volatile boolean locked = false;

        synchronized void lock() {
            while (locked) {
                wait();
            }
            locked = true;
        }

        synchronized void unlock() {
            locked = false;
            notifyAll();
        }

        synchronized boolean tryLock(long timeout, TimeUnit unit)
                throws InterruptedException {
            long endOfTimeout = System.nanoTime()
                    + unit.toNanos(timeout);
            while (locked) {
                if (Thread.currentThread().isInterrupted()) {
                    return false;
                }
                if (endOfTimeout <= System.nanoTime()) {
                    return false;
                }
                wait();
            }
            return true;
        }
    }

    public static void main(String[] args)
            throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        final Container originContainer = new Container();
        final Container targetContainer = new Container();

        Runnable runnable = new ElementCount() {
            @Override
            public void run() {
                try {
                    Thread.sleep(1000);
                    while (true) {
                        add((int) (Math.random() * 10));
                        if (getCount() > 5) {
                            break;
                        }
                        Thread.sleep(100);
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.execute(runnable);
        executor.execute(runnable);

        final int numElementsToSwap = 3;

        Future<Boolean> swapFuture = executor.submit(new Callable<Boolean>() {
            @Override
            public Boolean call() throws Exception {
                return doSwap(originContainer, targetContainer,
                        numElementsToSwap, 1000, TimeUnit.MILLISECONDS);
            }
        });

        System.out.println(swapFuture.get());

        executor.shutdown();
    }

    static boolean doSwap(Container originContainer, Container targetContainer,
                           int numElementsToSwap, long timeout, TimeUnit timeUnit)
            throws InterruptedException {
        for (int i = 0; i < MAX_ATTEMPTS; i++) {
            if (originContainer.tryLock(timeout, timeUnit)
                    && targetContainer.tryLock(timeout, timeUnit)) {
                try {
                    if (getCount(originContainer) >= numElementsToSwap) {
                        while (numElementsToSwap > 0) {
                            int element = swap(originContainer, targetContainer);
                            System.out.println("Swapped " + element + " from origin to target.");
                            numElementsToSwap--;
                        }
                        return true;
                    } else {
                        throw new InsufficientElementsException(
                                "Origin container has insufficient elements for the swap operation.");
                    }
                } finally {
                    if (originContainer.tryLock(timeout, timeUnit)) {
                        targetContainer.unlock();
                    }
                }
            } else {
                originContainer.unlock();
                targetContainer.unlock();

                long delay = calculateDelay(i);
                System.out.println("Lock acquisition failed. Retrying in " + delay + " ms.");
                Thread.sleep(delay);
            }
        }

        return false;
    }

    static int swap(Container origin, Container target) {
        int element = origin.getCount();
        origin.add(-1);
        target.add(element);
        return element;
    }

