  final Resonance resonance;

  Rune(Constellation c, Resonance r) {
    this.constellation = c;
    this.resonance = r;
  }

  @Override
  public int compareTo(Rune other) {
    int cmpConstellations = this.constellation.compareTo(other.constellation);
    if (cmpConstellations == 0) return this.resonance.compareTo(other.resonance);
    return cmpConstellations;
  }
}

class Harmony implements Comparable<Harmony> {
  final List<Rune> runes;

  Harmony(List<Rune> runes) { this.runes = Collections.unmodifiableList(runes); }

  @Override
  public int compareTo(Harmony other) {
    return -1 * runicArtComparator().compare(this, other);
  }

  private Comparator<RunicArt> runicArtComparator() {
    return (rune1, rune2) -> {
      Constellation constellation = rune1.constellation;
      if (!constellation.equals(rune2.constellation)) return constellation.compareTo(rune2.constellation);
      Resonance resonance = rune1.resonance;
      if (!resonance.equals(rune2.resonance)) return ((resonance == Resonance.POSITIVE) ? 1 : -1) + (rune1.compareTo(rune2));
      return rune1.compareTo(rune2);
    };
  }
}

