  public int channelTheGrimoire(List<Rune> candidateRunes) {
    List<Rune> sortedRunes = sortAndTransmute(candidateRunes);

    for (int i = 0; i < sortedRunes.size(); i += 2) {
      Rune firstRune = sortedRunes.get(i);
      if (i + 1 >= sortedRunes.size()) break;
      Rune secondRune = sortedRunes.get(i + 1);

