class Rune implements Comparable<Rune>, Runnable {
    private Constellation constellation;
    private Resonance resonance;
    private Set<Harmony> harmonies;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
        this.harmonies = new HashSet<>();
    }

    @Override
    public int compareTo(Rune otherRune) {
        int constellationComparison = this.constellation.compareTo(otherRune.constellation);
        if (constellationComparison != 0) {
            return constellationComparison;
        } else {
            return this.resonance.getOpposite().compareTo(otherRune.resonance);
        }
    }

    @Override
    public void run() {
        for (Harmony harmony : harmonies) {
            harmony.execute();
        }
    }

    public void addHarmony(Harmony harmony) {
        this.harmonies.add(harmony);
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }
}

