    public Harmony(Set<Rune> runes) {
        this.runes = runes;
    }

    @Override
    public void run() {
        for (Rune rune : runes) {
            if (rune.getConstellation().equals(runes.iterator().next().getConstellation())
                    && rune.getResonance().getOpposite().equals(runes.iterator().next().getResonance())) {
                System.out.println("Harmony formed");
