class HarmonyHandler implements Runnable {
    private Collection<Rune> candidateRunes;
    private ExecutorService executor;

    public HarmonyHandler(Collection<Rune> candidateRunes) {
        this.candidateRunes = candidateRunes;
    }

    public int execute() {
        List<Rune> runeList = new ArrayList<>(candidateRunes);
        Collections.sort(runeList);

        for (int i = 0; i < runeList.size(); i += 2) {
            Rune firstRune = runeList.get(i);
            if (i + 1 < runeList.size()) {
                Rune secondRune = runeList.get(i + 1);
