this.ark = new Ark();
}

public int loadTheArk(Collection<Animal> candidates) {
SortedSet<Animal> animals;
int numPairs = 0;
Animal candidate = null;

animals = new TreeSet<>(new SpeciesGenderComparator());
animals.addAll(candidates);
for (Animal a : animals) {
if (candidate == null || !candidate.isPotentialMate(a)) {
candidate = a;
} else {
ark.load(new AnimalPair(candidate, a));
++numPairs;
candidate = null;
}
}
return numPairs;
}

public static void main(String[] args) throws InterruptedException {
Animals animalsApp = new Animals();

Collection<Animal> group1 = createSampleAnimals(4);
Collection<Animal> group2 = createSampleAnimals(4);

ExecutorService executor = Executors.newFixedThreadPool(2);

executor.submit(() -> {
int pairs = animalsApp.loadTheArk(group1);
System.out.println(Thread.currentThread().getName() + " loaded " + pairs + " pairs.");
});

executor.submit(() -> {
