private final Set<AnimalPair> loadedAnimals = Collections.synchronizedSet(new HashSet<>());

public void load(AnimalPair pair) {
loadedAnimals.add(pair);
System.out.println(Thread.currentThread().getName() + " loaded a pair: " + pair.hashCode());
}
}
