    public RuneNode(List<RuneNode> children) {
        this.children = Collections.unmodifiableList(children);
    }

    @Override
    public void cast() {
        result = 0;
        for (RuneNode child : children) {
            child.cast();
            result += child.getResult();
        }
    }

    public int getResult() {
        return result;
    }
}

class SequentialProcessor {
    public static <T extends Charm> void process(List<T> charms) {
        for (Charm charm : charms) {
            charm.cast();
        }
    }

    public static <T extends RuneNode> int process(RuneNode root) {
        root.cast();
        return root.getResult();
    }
}

class ConcurrentProcessor {
    private final ExecutorService executor;

    public ConcurrentProcessor(int threadPoolSize) {
        this.executor = Executors.newFixedThreadPool(threadPoolSize);
    }

    public static <T extends Charm> void process(List<T> charms, ExecutorService executor) {
        for (Charm charm : charms) {
            executor.execute(charm::cast);
        }
    }

    public static <T extends RuneNode> int process(RuneNode root, ExecutorService executor) throws InterruptedException, ExecutionException {
        Future<Integer>[] futures = new Future[root.getChildren().size()];
        for (int i = 0; i < futures.length; i++) {
            futures[i] = executor.submit(() -> {
                RuneNode child = root.getChildren().get(i);
                child.cast();
                return child.getResult();
            });
        }
        int result = 0;
        for (Future<Integer> future : futures) {
            result += future.get();
        }
        return result;
    }

    public void shutdown() {
        executor.shutdown();
    }
}

