    public int[] call() {
        List<Future<?>> futures = new ArrayList<>();
        Stack<SigilNode> stack = new Stack<>();
        stack.push(node);
        while (!stack.isEmpty()) {
            SigilNode currentNode = stack.pop();
            futures.add(executor.submit(() -> {
                int result = currentNode.calculateResult();
                return result;
            }));
            for (SigilNode child : currentNode.getChildren())
                stack.push(child);
        }
        // Wait until all tasks complete before returning the result collection.
        for (Future<?> future : futures) {
            try {
                Integer result = (Integer) future.get();
                futures.set(future, result);
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
