public class CrystalCarousel {
    private final int maxSize;
    private final Object[] buffer;
    private int count = 0;
    private final Lock lock = new ReentrantLock();

    public CrystalCarousel(int maxSize) {
        this.maxSize = maxSize;
        this.buffer = new Object[maxSize];
    }

    public boolean put(Crystal x) throws InterruptedException {
        lock.lock();
        try {
            while (count == maxSize) {
                buffer[count] = null; // Remove the oldest item
                count--;
                Thread.sleep(1); // Wait for a bit to simulate insertion delay
            }
            if (count < maxSize) {
                buffer[count++] = x;
                return true;
            } else {
                return false;
            }
        } finally {
            lock.unlock();
        }
    }

    public Crystal take() throws InterruptedException {
        lock.lock();
        try {
            while (count == 0) {
                Thread.sleep(1); // Wait for a bit to simulate extraction delay
            }
            if (count > 0) {
                Crystal crystal = (Crystal) buffer[--count];
                buffer[count] = null;
                return crystal;
            } else {
                return null;
            }
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        return count == 0;
    }

