public class PotionLoop {
    private final int size;
    private final Potion[] potions;
    private final ReentrantLock lock;
    private final Condition emptyCondition;
    private final Condition fullCondition;

    public PotionLoop(int size) {
        this.size = size;
        this.potions = new Potion[size];
        this.lock = new ReentrantLock();
        this.emptyCondition = lock.newCondition();
        this.fullCondition = lock.newCondition();
    }

    public void put(Potion x) throws InterruptedException {
        lock.lock();
        try {
            while (full()) {
                fullCondition.await();
            }
            int i = nextIndex();
            potions[i] = x;
            emptyCondition.signal();
        } finally {
            lock.unlock();
        }
    }

    public Potion take() throws InterruptedException {
        lock.lock();
        try {
            while (!empty()) {
                emptyCondition.await();
            }
            int i = nextIndex();
            Potion potion = potions[i];
            potions[i] = null;
            fullCondition.signal();
            return potion;
        } finally {
            lock.unlock();
        }
    }

    private boolean full() {
        for (int i : getNextIndices()) {
            if (potions[i] != null) {
