public class SigilLedger {

    private final Map<String, String> runesMap;
    private final ReentrantReadWriteLock lock;

    public SigilLedger(Map<String, String> runesMap) {
        this.runesMap = runesMap;
        this.lock = new ReentrantReadWriteLock();
    }

    public void addRune(String rune, String sigil) {
        lock.writeLock().lock();
        try {
            runesMap.put(rune, sigil);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeRune(String rune) {
        lock.writeLock().lock();
        try {
            runesMap.remove(rune);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public String getSigil(String rune) {
        lock.readLock().lock();
        try {
            return runesMap.get(rune);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {

        Map<String, String> runesMap = new HashMap<>();
        SigilLedger ledger = new SigilLedger(runesMap);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Runnable task1 = () -> {
            ledger.addRune("rune1", "sigil1");
            ledger.addRune("rune2", "sigil2");
        };
        Runnable task2 = () -> {
            ledger.removeRune("rune1");
            System.out.println(ledger.getSigil("rune2"));
        };

