class MysticCounter {
    private int essence;

    public synchronized int get() {
        return essence;
    }

    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        int oldEssence = essence;
        if (essence == expectedEssence) {
            essence = newEssence;
        }
        return oldEssence;
    }

    public synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
        return compareAndSwap(expectedEssence, newEssence) != expectedEssence;
    }
}

