        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        Future<Constellation<String, MutableOrb>> futureResult = executor.submit(new Callable<Constellation<String, MutableOrb>>() {
            @Override
            public Constellation<String, MutableOrb> call() {
                return deepClone(constellation);
            }
        });
