import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;

class CelestialHourglass implements Runnable {
    private boolean activated;
    private long dawnTime;
    private long duskTime;
    private ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

    @Override
    public void run() {
        synchronized (this) {
            if (!activated) {
                activated = true;
                dawnTime = System.nanoTime();
            } else {
                duskTime = System.nanoTime();
            }
        }
    }

    public void reset() {
        synchronized (this) {
            activated = false;
            duskTime = 0;
        }
    }

    public long getFlow() {
        synchronized (this) {
            return duskTime - dawnTime;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        CelestialHourglass hourglass = new CelestialHourglass();
        executor.execute(hourglass);
        Thread.sleep(2000);
        hourglass.reset();
        System.out.println("Flow: " + hourglass.getFlow() + " nanoseconds");
        executor.shutdown();
    }
}

