import java.util.concurrent.Semaphore;

class BoundedBuffer {
    private final int[] buffer = new int[10];
    private int itemCount = 0;
    private Semaphore availableItems = new Semaphore(0);
    private Semaphore remainingSpace = new Semaphore(10);

    public synchronized void put(int x) throws InterruptedException {
        remainingSpace.acquire();
        availableItems.release();
        buffer[itemCount++] = x;
    }

    public synchronized int take() throws InterruptedException {
        availableItems.acquire();
        remainingSpace.release();
        return buffer[--itemCount];
    }

    public boolean isEmpty() {
        return itemCount == 0;
    }

    public boolean isFull() {
        return itemCount == 10;
    }
}

