        remainingSpacesSemaphore.acquire();
        availableItemsSemaphore.acquire();
        buffer[tail] = x;
        if (tail == capacity - 1) {
            tail = 0;
        } else {
            tail++;
        }
        count++;
    }

    public Object take() throws InterruptedException {
        availableItemsSemaphore.acquire();
        remainingSpacesSemaphore.acquire();
        Object item = buffer[head];
        if (head == capacity - 1) {
            head = 0;
        } else {
            head++;
        }
        count--;
        return item;
    }

    public boolean isEmpty() {
        return count == 0;
    }

    public boolean isFull() {
        return count == capacity;
    }
}

