import java.math.BigInteger;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

class ImmutableCache {
    private final BigInteger value;

    public ImmutableCache(BigInteger value) {
        this.value = value;
    }

    public BigInteger getValue() {
        return value;
    }
}

public class MyServlet extends HttpServlet implements Runnable {

    private volatile ImmutableCache cache = new ImmutableCache(BigInteger.ZERO);

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        BigInteger input = extractInput(request);
        if (cache.getValue().equals(input)) {
            sendResponse(response, input);
        } else {
            synchronized (this) {
                BigInteger result = recalculateResult(input);
                cache = new ImmutableCache(result);
                sendResponse(response, result);
            }
        }
    }

    private BigInteger recalculateResult(BigInteger input) {
        return input;
    }

    private void sendResponse(HttpServletResponse response, BigInteger value)
            throws ServletException, IOException {
        response.getWriter().write(value.toString());
        response.setStatus(200);
    }

    private BigInteger extractInput(HttpServletRequest request) {
        String inputValue = request.getParameter("input");
        return new BigInteger(inputValue);
    }

    public static void main(String[] args) {
        MyServlet servlet = new MyServlet();
        Thread thread = new Thread(servlet);
        thread.start();
    }
}

