        private final java.util.concurrent.ConcurrentHashMap<BigInteger, BigInteger[]> map = new java.util.concurrent.ConcurrentHashMap<>();

        public BigInteger get(BigInteger value) {
            return map.get(value);
        }

        public void put(BigInteger key, BigInteger[] value) {
