public class CacheServlet extends HttpServlet implements Runnable {
    private final volatile Cache cache = new Cache();

    public void run() {
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        BigInteger value = BigInteger.valueOf(System.currentTimeMillis());
        synchronized (cache) {
            if (!cache.isCached(value)) {
                cache.cacheResult(value, new Result[] {value});
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
