        }
        executor.shutdown();
    }

    private static class Cache {
        private final volatile Result[] cache;

        public Cache() {
            this.cache = new Result[1];
        }

        public synchronized boolean isCached(BigInteger value) {
            for (Result result : cache) {
                if (result != null && result.getValue().equals(value)) {
                    return true;
                }
            }
            return false;
        }

        public synchronized void cacheResult(BigInteger value, Result[] results) {
            while (cache.length > 1) {
                cache = new Result[cache.length / 2];
            }
            cache[0] = results[0];
        }
    }

    private static class Result {
        private final BigInteger value;

        public Result(BigInteger value) {
            this.value = value;
        }

        public BigInteger getValue() {
            return value;
        }
    }
