public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Point> vehicleMap = new ConcurrentHashMap<>();

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        for (Map.Entry<String, Point> entry : initialLocations.entrySet()) {
            vehicleMap.put(entry.getKey(), entry.getValue());
        }
    }

    public Map<String, Point> getLocations() {
        return new ConcurrentHashMap<>(vehicleMap);
    }

    public Point getLocation(String id) {
        return vehicleMap.get(id);
    }

    public void setLocation(String id, int x, int y) {
        if (!vehicleMap.containsKey(id)) {
            throw new IllegalArgumentException("Vehicle does not exist");
        }
        vehicleMap.computeIfPresent(id, (k, v) -> new Point(x, y));
    }

    public Map<String, Point> getLocationsAsStatic() {
        return new ConcurrentHashMap<>(vehicleMap);
    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(new HashMap<>());

        Thread updater1 = new Thread(() -> {
            try {
                Thread.sleep(500);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            tracker.setLocation("vehicle1", 0, 0);
        });

