import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class PrimeGenerator implements Runnable {
    private volatile boolean running = true;
    private final List<Integer> primeNumbers = new ArrayList<>();
    private static final int MAX_PRIME_NUMBER = 100;

    public synchronized void cancel() {
        this.running = false;
    }

    @Override
    public synchronized void run() {
        try {
            while (running && primeNumbers.size() < MAX_PRIME_NUMBER) {
                int number = generateNextPrime(primeNumbers);
                if (number != -1) {
                    primeNumbers.add(number);
                }
                Thread.sleep(1000); // wait for 1 second
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private int generateNextPrime(List<Integer> primes) {
        int number = 2;
        while (true) {
            boolean isPrime = true;
            for (int prime : primes) {
                if (prime > Math.sqrt(number)) {
                    break;
                }
                if (number % prime == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                return number;
            }
            number++;
        }
    }

    public synchronized List<Integer> getGeneratedPrimes() {
        return new ArrayList<>(primeNumbers);
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        PrimeGenerator primeGenerator = new PrimeGenerator();

        executor.execute(primeGenerator);

        try {
            Thread.sleep(2000); // wait for 2 seconds
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        primeGenerator.cancel(); // cancel the generation process

        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        List<Integer> primes = primeGenerator.getGeneratedPrimes();

        System.out.println("Generated Prime Numbers: " + primes);
    }
}

