class StripedMap {
    static class Node {
        int key;
        String value;
        Node next;

        Node(int key, String value) {
            this.key = key;
            this.value = value;
        }
    }

    private final Node[] buckets;
    private final Object[] locks;
    private static final int N_LOCKS = 16;

    StripedMap() {
        buckets = new Node[32];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int hashIndex(int key) {
        return Math.abs(key) % buckets.length;
    }

    public synchronized String get(int key) throws InterruptedException {
        int index = hashIndex(key);
        Object lock = locks[index % N_LOCKS];
        synchronized (lock) {
            Node node = buckets[index];
            while (node != null) {
                if (node.key == key) {
                    return node.value;
                }
                node = node.next;
            }
        }
        throw new RuntimeException("Key not found");
    }

    public void clear() throws InterruptedException {
        for (int i = 0; i < N_LOCKS; i++) {
            Object lock = locks[i];
            synchronized (lock) {
                Node currentBucket = buckets[i];
                while (currentBucket != null) {
                    Node nextNode = currentBucket.next;
                    if (nextNode == null) {
                        break;
                    }
                    buckets[i] = nextNode;
                    currentBucket = nextNode;
                    currentBucket.next = null;
                }
            }
        }
