    }

    public synchronized Object get(Object key) {
        int index = hashIndex(key);
        return buckets[index].getValue(key);
    }

    public synchronized void clear() {
        for (int i = 0; i < buckets.length; i++) {
            buckets[i] = null;
        }
    }

    private int hashIndex(Object key) {
        return Math.abs(key.hashCode()) % N_LOCKS;
    }

    static class Node {
        Object key;
        Object value;
        Node next;

        public Node(Object key, Object value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }

        public Object getValue(Object key) {
            if (key.equals(this.key)) {
                return value;
            } else if (next != null) {
                return next.getValue(key);
            }
            return null;
        }
    }

    public static void main(String[] args) {
        StripedMap map = new StripedMap(16);

        // Add entries to the map
        map.put("1", "One");
        map.put("2", "Two");
        map.put("3", "Three");

        // Get values from the map
        System.out.println(map.get("1"));  // Output: One
        System.out.println(map.get("2"));  // Output: Two

        // Clear the map
        map.clear();
        System.out.println(map.get("1"));  // Output: null
    }

    public synchronized void put(Object key, Object value) {
        int index = hashIndex(key);
        if (buckets[index] == null) {
            buckets[index] = new Node(key, value, null);
        } else {
            Node current = buckets[index];
            while (current.next != null) {
                if (key.equals(current.key)) {
                    current.value = value;
                    return;
                }
                current = current.next;
            }
            if (key.equals(current.key)) {
                current.value = value;
            } else {
                current.next = new Node(key, value, null);
            }
        }
    }
