class StripedMap {
    private static final int N_LOCKS = 16;
    private Node[] buckets;
    private Lock[] locks;

    public StripedMap(int capacity) {
        this.buckets = new Node[capacity];
        this.locks = new ReentrantLock[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            this.locks[i] = new ReentrantLock();
        }
    }

    public int hashIndex(int key) {
        return Math.abs(key) % buckets.length;
    }

    public Object get(Object key) {
        final int index = hashIndex((int) key);
        Lock lock = locks[index];
        lock.lock();
        try {
            Node node = buckets[index];
            while (node != null) {
                if (((Node) key).compareTo(node) == 0) {
                    return node.value;
                }
                node = node.next;
            }
            return null;
        } finally {
            lock.unlock();
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            Lock lock = locks[i];
            lock.lock();
            try {
                buckets[i] = null;
            } finally {
                lock.unlock();
            }
        }
    }

    private static class Node implements Comparable<Node> {
        int key;
        Object value;
        Node next;

        public Node(int key, Object value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public int compareTo(Node other) {
            return this.key - other.key;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        StripedMap map = new StripedMap(100);
        for (int i = 0; i < 50; i++) {
            map.put(i, String.valueOf(i));
        }
        System.out.println(map.get(25)); // prints "25"
        map.clear();
        System.out.println(map.get(25)); // prints null
    }
