import java.math.BigInteger;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class ImmutableCache {

    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = new BigInteger[factors.length];
        System.arraycopy(factors, 0, this.factors, 0, factors.length);
    }

    public static void main(String[] args) {
        BigInteger[] cachedFactors = factorialCalculationTask(new BigInteger("5")).get();
        ImmutableCache cache = new ImmutableCache(cachedFactors[0], cachedFactors);

        Thread retrievalThread = new Thread(() -> {
            BigInteger[] retrievedFactors = cache.getFactors();
            System.out.println(retrievedFactors != null ? "Retrieved factors: " + retrievedFactors : "No matching number found");
        });

        ForkJoinPool pool = new ForkJoinPool();
        pool.submit(retrievalThread).join();

    }

    public BigInteger[] getFactors() {
        if (this.number == null) return null;
        synchronized (ImmutableCache.class) {
            if (this.factors == null) {
                this.factors = factorialCalculationTask(this.number).get();
            }
        }
        return this.factors.clone();
    }

    private static class FactorialCalculationTask extends RecursiveTask<BigInteger[]> {

        private final BigInteger number;

        public FactorialCalculationTask(BigInteger number) {
            this.number = number;
        }

        @Override
        protected BigInteger[] compute() {
            if (number.equals(BigInteger.ONE)) return new BigInteger[]{});
            BigInteger factor = BigInteger.ZERO;
            BigInteger[] result = new BigInteger[0];
            for (BigInteger i = BigInteger.ONE; ; i = i.add(BigInteger.ONE)) {
                if (i.compareTo(number) > 0) break;
                if (number.mod(i).equals(BigInteger.ZERO)) {
                    result = new BigInteger[i.intValue()];
                    for (int j = 0; j < i.intValue(); j++) {
                        result[j] = i;
                    }
                    factor = i;
                    break;
                }
            }
            return result.concat(factorialCalculationTask(number.divide(factor)).compute());
        }
    }

    private static FactorialCalculationTask factorialCalculationTask(BigInteger number) {
        return new FactorialCalculationTask(number);
    }
}

