/**
* Immutable cache storing one number and its factors.
*/
final class OneValueCache {
private final BigInteger lastNumber;
private final BigInteger[] lastFactors;

public OneValueCache(BigInteger i, BigInteger[] factors) {
this.lastNumber = i;
if (factors != null) {
this.lastFactors = Arrays.copyOf(factors, factors.length);
} else {
this.lastFactors = null;
}
}

public BigInteger[] getFactors(BigInteger i) {
if (lastNumber == null || !lastNumber.equals(i)) {
return null;
}
if (lastFactors == null) {
return null;
}
return Arrays.copyOf(lastFactors, lastFactors.length);
}
}

/**
* A factorizer with synchronized cache access.
* Avoids using volatile or thread pool to remain JPF-compatible.
*/
public class FactorizerWithCache {
private static OneValueCache cache = new OneValueCache(null, null);

public static BigInteger[] factor(BigInteger n) {
List<BigInteger> factors = new ArrayList<>();
BigInteger i = BigInteger.valueOf(2);

while (i.multiply(i).compareTo(n) <= 0) {
while (n.mod(i).equals(BigInteger.ZERO)) {
factors.add(i);
n = n.divide(i);
}
i = i.add(BigInteger.ONE);
}

if (n.compareTo(BigInteger.ONE) > 0) {
factors.add(n);
}

return factors.toArray(new BigInteger[0]);
}

public static void handleRequest(BigInteger number, int threadId) {
BigInteger[] cachedFactors;

synchronized (FactorizerWithCache.class) {
cachedFactors = cache.getFactors(number);

if (cachedFactors == null) {
System.out.println("Thread " + threadId + ": Cache miss for " + number + ", computing...");
BigInteger[] factors = factor(number);
cache = new OneValueCache(number, factors);
cachedFactors = cache.getFactors(number);
} else {
System.out.println("Thread " + threadId + ": Cache hit for " + number);
}
}

System.out.print("Thread " + threadId + ": Factors of " + number + " are ");
System.out.println(Arrays.toString(cachedFactors));
}

public static void main(String[] args) throws InterruptedException {
BigInteger numberToFactor = new BigInteger("100");

Thread t1 = new Thread(() -> handleRequest(numberToFactor, 1));
Thread t2 = new Thread(() -> handleRequest(numberToFactor, 2));

t1.start();
t2.start();

t1.join();
t2.join();

System.out.println("All threads have finished execution.");
}
}

