    public ImproveList(List<Object> list) {
        this.list = new ArrayList<>(list);
    }

    public synchronized boolean putIfAbsent(Object key, Object value) {
        int index = 0;
        while (index < list.size()) {
            if (list.get(index) == null || !key.equals(list.get(index))) {
                break;
            }
            final int indexFinal = index++;
            if (!list.set(indexFinal, value)) {
                return false;
            }
        }
        return true;
    }

