class MonitorVehicleTracker {
    private final Map<String, MutablePoint> vehicleMap;

    public MonitorVehicleTracker(Map<String, MutablePoint> initialMap) {
        this.vehicleMap = deepCopy(initialMap);
    }

    private synchronized Map<String, MutablePoint> deepCopy(Map<String, MutablePoint> originalMap) {
        Map<String, MutablePoint> copiedMap = new HashMap<>();
        for (Map.Entry<String, MutablePoint> entry : originalMap.entrySet()) {
            MutablePoint point = new MutablePoint(entry.getValue().getX(), entry.getValue().getY());
            copiedMap.put(entry.getKey(), point);
        }
        return Collections.unmodifiableMap(copiedMap);
    }

    public synchronized Map<String, MutablePoint> getLocations() {
