import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class NonBlockingStack {
    private static class Node {
        int item;
        Node next;

        public Node(int item, Node next) {
            this.item = item;
            this.next = next;
        }
    }

    private final Node head;
    private final AtomicReference<Node> top;

    public NonBlockingStack() {
        head = null;
        top = new AtomicReference<>(null);
    }

    public boolean push(int item) {
        Node newTop = new Node(item, head);
        return top.compareAndSet(null, newTop);
    }

    public int pop() {
        for (;;) {
            Node currentTop = top.get();
            if (currentTop == null)
                return -1; // stack empty
            Node nextTop = currentTop.next;
            if (top.compareAndSet(currentTop, nextTop))
