import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

public class DelegatingVehicleTracker {
    private final Map<Long, VehicleLocation> vehicleLocations;

    public DelegatingVehicleTracker(Map<Long, VehicleLocation> initialLocations) {
        this.vehicleLocations = new ConcurrentHashMap<>(initialLocations);
    }

    public VehicleLocation getLocation(long vehicleId) {
        return vehicleLocations.get(vehicleId);
    }

    public boolean setLocation(long vehicleId, VehicleLocation location) {
        if (!vehicleLocations.containsKey(vehicleId)) {
            throw new RuntimeException("Vehicle ID does not exist");
        }
        return vehicleLocations.put(vehicleId, location) == null;
    }

    public Map<Long, VehicleLocation> getAllLocations() {
        return vehicleLocations.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
    }

    public Map<Long, VehicleLocation> getSnapshotOfAllLocations() {
        return new ConcurrentHashMap<>(vehicleLocations);
    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(Map.of(1L, VehicleLocation.create(2, 3), 2L, VehicleLocation.create(4, 5)));

        Thread updaterThread = new Thread(() -> {
            try {
                Thread.sleep(1000);
                tracker.setLocation(1L, VehicleLocation.create(3, 4));
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });

        Thread printerThread = new Thread(() -> System.out.println(tracker.getAllLocations()));

        updaterThread.start();
        printerThread.start();

        updaterThread.join();
        printerThread.join();
    }

    static final class VehicleLocation {
        private final int x;
        private final int y;

        private VehicleLocation(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public static VehicleLocation create(int x, int y) {
            return new VehicleLocation(x, y);
        }

        @Override
        public String toString() {
            return "VehicleLocation{" +
                    "x=" + x +
                    ", y=" + y +
                    '}';
        }
    }
}

