public class DelegatingVehicleTracker {
    private final Map<Integer, Vehicle> vehicleMap = new ConcurrentHashMap<>();

    public DelegatingVehicleTracker(Map<Integer, Vehicle> initialLocations) {
        for (Map.Entry<Integer, Vehicle> entry : initialLocations.entrySet()) {
            vehicleMap.put(entry.getKey(), entry.getValue());
        }
    }

    public Vehicle getLocation(int vehicleId) {
        return vehicleMap.get(vehicleId);
    }

    public boolean setLocation(int vehicleId, double x, double y) {
        return vehicleMap.computeIfPresent(vehicleId, (id, vehicle) -> new Vehicle(x, y));
    }

    public Map<Integer, Vehicle> getAllLocations() {
        return vehicleMap.entrySet().stream()
                .collect(Collectors.toMap(Map.Entry::getKey,
                        entry -> new Vehicle(entry.getValue().getX(), entry.getValue().getY())));
    }

    public Map<Integer, Vehicle> getStaticAllLocations() {
        return new ConcurrentHashMap<>(vehicleMap);
    }

    public static void main(String[] args) throws InterruptedException {
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(Map.of(1, new Vehicle(0, 0), 2, new Vehicle(0, 0)));

        // Update location of vehicle with ID 1
        boolean success = tracker.setLocation(1, 10, 20);
        System.out.println("Set location of vehicle 1: " + (success ? "Success" : "Failed"));

        // Get current locations
