        System.out.println("All locations:");
        for (Map.Entry<Integer, Vehicle> entry : allLocations.entrySet()) {
            System.out.println(entry.getKey() + ": (" + entry.getValue().getX() + ", " + entry.getValue().getY() + ")");
        }

        // Get static snapshot of current locations
        Map<Integer, Vehicle> staticAllLocations = tracker.getStaticAllLocations();
