class PairingService {
    private static final PairingService instance = new PairingService();
    private final Queue<Animal> singles = new ConcurrentLinkedQueue<>();

    private PairingService() {}

    public static PairingService getInstance() {
        return instance;
    }

    public void addSingle(Animal animal) {
        singles.add(animal);
    }

    public void attemptPair(Animal single) throws InterruptedException {
        while (singles.isEmpty()) {
            Thread.sleep(100); // Minimize loop iteration count
        }
        Animal mate = singles.poll();
        if (mate != null && mate.getSpecies().equals(single.getSpecies())
                && mate.getGender().isCompatibleWith(single.getGender())) {
            single.setPaired(true);
            mate.setPaired(true);
        } else {
            singles.add(single); // If no compatible mate found, add back to singles
        }
    }

    public int loadTheArk(List<Animal> candidates) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(2); // Use minimal iteration count and fixed thread pool

        List<Future<?>> futures = new ArrayList<>();
        for (Animal animal : candidates) {
            Animal pair = new Animal(animal.getSpecies(), animal.getGender());
            pair.run();
            futures.add(executor.submit(pair));
        }

        int pairsFormed = 0;
        while (!futures.isEmpty()) {
            Iterator<Future<?>> it = futures.iterator();
            while (it.hasNext()) {
                Future<?> future = it.next();
                try {
                    if (future.get().isPaired()) { // Count only the paired animals
                        pairsFormed++;
                        it.remove(); // Remove from iterator once paired
                    }
                } catch (InterruptedException | ExecutionException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }

        executor.shutdown();
        return pairsFormed;
    }
}

