                // Wait at the start gate
                startGate.await();

                long startTime = System.nanoTime();

                // Measure time for this block
                endGate.await();
                long endTime = System.nanoTime();

                System.out.println("Total duration: " + (endTime - startTime) / 1000000.0 + " ms");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "Main Thread");

        ConcurrencyTest task = new ConcurrencyTest(startGate, endGate);

        for (int i = 1; i <= THREAD_COUNT; i++) {
            new Thread(task).start();
        }

        // Open the start gate
        startGate.countDown();

        // Wait at the end gate for all threads to finish their tasks
        endGate.await();

        mainThread.start();
    }
