import java.math.BigInteger;
import java.util.*;

public class PrimeGenerator implements Runnable {
private final List<BigInteger> primes = new ArrayList<>();
private volatile boolean cancelled = false;
private final int maxPrimes;

public PrimeGenerator(int maxPrimes) {
this.maxPrimes = maxPrimes;
}

public void run() {
BigInteger p = BigInteger.ONE;
while (!cancelled && primes.size() < maxPrimes) {
p = p.nextProbablePrime();
synchronized (this) {
primes.add(p);
}
// Optional: remove sleep to speed up, or keep a very short sleep
try {
Thread.sleep(1);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
break;
}
}
}

public void cancel() {
cancelled = true;
}

public synchronized List<BigInteger> get() {
return new ArrayList<>(primes);
}

public static List<BigInteger> generatePrimes(int count) throws InterruptedException {
PrimeGenerator generator = new PrimeGenerator(count);
Thread thread = new Thread(generator);
thread.start();
thread.join(); // Wait until generator finishes generating count primes
return generator.get();
}

public static void main(String[] args) {
try {
int primeCount = 10; // Generate 10 primes
List<BigInteger> primes = generatePrimes(primeCount);

System.out.println("Generated " + primes.size() + " primes.");

