import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

class PrimeProducer implements Runnable {
    private final BlockingQueue<Integer> queue;
    private volatile boolean stopRequested;

    public PrimeProducer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            for (int i = 2; !stopRequested && isPrime(i); ) {
                int prime = getNthPrime(i);
                queue.put(prime);
                System.out.println(Thread.currentThread().getName() + " produced: " + prime);
                Thread.sleep(500);
                i++;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private boolean isPrime(int number) {
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    private int getNthPrime(int n) {
        int count = 1;
        int number = 2;
        while (count < n) {
            number++;
            if (isPrime(number)) {
                count++;
            }
        }
        return number;
    }

    public void stop() {
        this.stopRequested = true;
    }
}

