    }
}

class TreeProcessor {
    private final ExecutorService executor;

    public TreeProcessor(ExecutorService executor) {
        this.executor = executor;
    }

    public <T extends Element> int process(Node<T> node) throws InterruptedException, ExecutionException {
        List<Future<Integer>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildren()) {
            Future<Integer> future = executor.submit(() -> child.process());
            futures.add(future);
        }
        int result = 0;
        for (Future<Integer> future : futures) {
            result += future.get();
        }
        return result;
    }

    public void shutdown() throws InterruptedException {
        executor.shutdown();
    }
}

public class Main {
    public static void main(String[] args) {
        SequentialProcessor sequentialProcessor = new SequentialProcessor();
        List<Node<Integer>> elements = createElements(2);
        sequentialProcessor.process(elements);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        ParallelProcessor parallelProcessor = new ParallelProcessor(executor);
        parallelProcessor.process(elements);
        executor.shutdown();

        TreeProcessor treeProcessor = new TreeProcessor(executor);
        Node<Integer> root = createTree(3);
        try {
            int result = treeProcessor.process(root);
            System.out.println(result);
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }
    }

    private static List<Node<Integer>> createElements(int count) {
        List<Node<Integer>> elements = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            Node<Integer> node = new Node<>();
            node.addChild(new Node<>()); // Add dummy child nodes
            elements.add(node);
        }
        return elements;
    }

    private static Node<Integer> createTree(int count) {
        Node<Integer> root = new Node<>();
        for (int i = 0; i < count; i++) {
            Node<Integer> parent = root;
            // Add dummy children to each node
            while (parent.getChildren().size() < 2) {
                parent.addChild(new Node<>());
            }
            if (i % 2 == 1) {
                parent.getChild(0).addChild(new Node<>()); // Add a child node for odd-indexed parents
            } else {
                parent.getChild(1).addChild(new Node<>()); // Add a child node for even-indexed parents
            }
        }
        return root;
    }
}

